9	
10	//! Per-process aarch64 address space.
11	//!
12	//! Slice 3.1a introduces this API but no proc consumes it yet — the kmain
13	//! smoke test exercises it standalone, and slice 3.1b will swap `userland.rs`
14	//! over so each EL0 stub gets its own [`AddrSpace`] instead of the shared
15	//! static L0/L1/L2/L3 arrays.
16	//!
17	//! The walk follows the same 4 KiB-granule, 4-level, 48-bit-VA layout that
18	//! [`super::mmu`] already documents and verifies on Limine handoff. Intermediate
19	//! tables (L1, L2, L3) are allocated on demand from the frame allocator —
20	//! [`AddrSpace::new`] only allocates the L0 root; each `map_page` walk
21	//! allocates whatever sub-tables are missing.
22	//!
23	//! All page-table writes go through HHDM — we never touch a table via its
24	//! own VA, because at slice-3.1a time the address space isn't activated.
25	//! Slice 3.1b's context switch will install [`AddrSpace::ttbr0_pa`] into
26	//! TTBR0_EL1; until then, AddrSpaces are passive data structures.
27	
28	use crate::arch::aarch64::mmu::{
29	    ATTR_IDX_NORMAL, PAGE_SHIFT, PTE_AF, PTE_AP_RO_EL0, PTE_AP_RW_EL0, PTE_PXN, PTE_SH_INNER,
30	    PTE_TABLE, PTE_UXN, PTE_VALID, PTES_PER_LEVEL, pte_attr_idx,
31	};
32	use crate::mm::{FRAME_SIZE, Frame, alloc_frame, free_frame, phys_to_hhdm};
33	use minixrs_kernel_shared::message::USER_VA_TOP;
34	
35	/// User-page permission. Maps onto the aarch64 stage-1 descriptor's AP +
36	/// PXN + UXN bits; kernel callers describe intent here and `prot_attrs()`
37	/// converts to the bit pattern.
38	#[derive(Copy, Clone, Debug)]
39	pub struct Prot {
40	    /// EL0 may write.
41	    pub writable: bool,
42	    /// EL0 may fetch from this page (code).
43	    pub executable: bool,
44	}
45	
46	impl Prot {
47	    pub const RO_CODE: Self = Self {
48	        writable: false,
49	        executable: true,
50	    };
51	    pub const RW_DATA: Self = Self {
52	        writable: true,
53	        executable: false,
54	    };
55	    pub const RO_DATA: Self = Self {
56	        writable: false,
57	        executable: false,
58	    };
59	}
60	
61	fn prot_attrs(prot: Prot) -> u64 {
62	    let ap = if prot.writable {
63	        PTE_AP_RW_EL0
64	    } else {
65	        PTE_AP_RO_EL0
66	    };
67	    let uxn = if prot.executable { 0 } else { PTE_UXN };
68	    PTE_AF | PTE_SH_INNER | ap | PTE_PXN | uxn | pte_attr_idx(ATTR_IDX_NORMAL)
69	}
70	
71	/// Errors from [`AddrSpace`] operations.
72	#[derive(Copy, Clone, Debug, PartialEq, Eq)]
73	pub enum MapError {
74	    /// Frame allocator returned `None`; no physical memory left for an
75	    /// intermediate page table or for the L0 root.
76	    OutOfMemory,
77	    /// `va` is not 4 KiB-aligned.
78	    Misaligned,
79	    /// `va` is outside the 48-bit user-VA window.
80	    OutOfRange,
81	    /// A leaf PTE is already present at `va` and the caller asked for a
82	    /// fresh mapping. Use [`AddrSpace::unmap_page`] to clear first.
83	    AlreadyMapped,
84	}
85	
86	/// One per-process page-table tree, rooted at the L0 frame whose PA goes
87	/// into TTBR0_EL1 on context switch.
88	pub struct AddrSpace {
89	    /// PA of the L0 page-table root. Always frame-aligned.
90	    pub ttbr0_pa: u64,
91	}
92	
93	impl AddrSpace {
94	    /// Build a fresh, empty address space. Allocates one frame for the L0
95	    /// root; intermediate L1/L2/L3 tables come later, on first `map_page`.
96	    pub fn new() -> Result<Self, MapError> {
97	        let l0 = alloc_frame().ok_or(MapError::OutOfMemory)?;
98	        // `alloc_frame` zeroes the frame, so the L0 starts all-invalid.
99	        Ok(Self {
100	            ttbr0_pa: l0.addr(),
101	        })
102	    }
103	
104	    /// Install a single 4 KiB mapping `va → pa` with the given permissions.
105	    ///
106	    /// Intermediate L1/L2/L3 tables are allocated from the frame allocator
107	    /// as needed. Returns `Err(AlreadyMapped)` if `va` already has a leaf
108	    /// PTE (callers must `unmap_page` first to replace).
109	    pub fn map_page(&mut self, va: u64, pa: u64, prot: Prot) -> Result<(), MapError> {
110	        map_page_in(self.ttbr0_pa, va, pa, prot)
111	    }
112	
113	    /// Clear the leaf PTE at `va`. Returns `Some(pa)` if a mapping was
114	    /// present, `None` otherwise. The freed PA is returned to the caller —
115	    /// it's the caller's job to `free_frame` if appropriate (the page
116	    /// might be a CoW share, a device PA, or stale; the address space
117	    /// itself doesn't know).
118	    ///
119	    /// Does not free intermediate L1/L2/L3 tables even if they become
120	    /// empty — that's left to [`Self::destroy`]. Avoiding incremental
121	    /// pruning keeps `unmap_page` O(walk) and matches what real MINIX 3
122	    /// does (lazy pruning at exec/exit time).
123	    pub fn unmap_page(&mut self, va: u64) -> Option<u64> {
124	        unmap_page_in(self.ttbr0_pa, va)
125	    }
126	
127	    /// Walk the page table to find the PA backing `va`, or `None` if `va`
128	    /// is unmapped.
129	    pub fn walk_pt(&self, va: u64) -> Option<u64> {
130	        check_va(va).ok()?;
131	        let l0 = self.ttbr0_pa;
132	        let l1 = next_table(l0, pte_index(va, 0))?;
133	        let l2 = next_table(l1, pte_index(va, 1))?;
134	        let l3 = next_table(l2, pte_index(va, 2))?;
135	        let pte = table_ref(l3)[pte_index(va, 3)];
136	        if pte & PTE_VALID == 0 {
137	            None
138	        } else {
139	            Some(pte & PA_MASK)
140	        }
141	    }
142	
143	    /// Free every intermediate L1/L2/L3 table and the L0 root.
144	    ///
145	    /// Leaf-page frames (the PAs that `map_page` installed) are *not*
146	    /// freed — the address space owns the page-table tree, not the pages
147	    /// it points at. The caller is responsible for tracking and freeing
148	    /// leaf frames before calling this; otherwise they leak. Phase 3.5's
149	    /// VM region tracker is what eventually owns leaf-frame lifetimes.
150	    pub fn destroy(self) {
151	        // Walk the L0 root, recursing into table descriptors. Page
152	        // descriptors (PTE_VALID & PTE_TABLE both set at L3) are leaves
153	        // and left alone; intermediate tables (PTE_VALID & PTE_TABLE at
154	        // L0/L1/L2) get recursed-into then freed.
155	        free_subtree(self.ttbr0_pa, 0);
156	        free_frame(Frame::from_addr(self.ttbr0_pa));
157	    }
158	}
159	
160	// ----- helpers --------------------------------------------------------------
161	
162	/// Install a single 4 KiB mapping `va → pa` into the page-table tree rooted
163	/// at `ttbr0_pa`, allocating intermediate L1/L2/L3 tables on demand.
164	///
165	/// This is the body of [`AddrSpace::map_page`], exposed as a free function
166	/// so the kernel can map into a proc's *live* address space given only the
167	/// `ttbr0_pa` stored on its [`Proc`](crate::proc::Proc) slot — without
168	/// reconstructing an owning [`AddrSpace`] value (whose future `destroy`
169	/// semantics would risk freeing a tree it does not own). The slice-3.2
170	/// page-fault handler and slice-3.3's `VMCTL_PT_MAP` both go through here.
171	///
172	/// All table access is via HHDM; the target AS need not be the active one.
173	pub fn map_page_in(ttbr0_pa: u64, va: u64, pa: u64, prot: Prot) -> Result<(), MapError> {
174	    check_va(va)?;
175	    if pa & (FRAME_SIZE as u64 - 1) != 0 {
176	        return Err(MapError::Misaligned);
177	    }
178	
179	    let l1 = ensure_next_table(ttbr0_pa, pte_index(va, 0))?;
180	    let l2 = ensure_next_table(l1, pte_index(va, 1))?;
181	    let l3 = ensure_next_table(l2, pte_index(va, 2))?;
182	    let l3_table = table_mut(l3);
183	    let idx = pte_index(va, 3);
184	    if l3_table[idx] & PTE_VALID != 0 {
185	        return Err(MapError::AlreadyMapped);
186	    }
187	    l3_table[idx] = make_page_desc(pa, prot_attrs(prot));
188	    Ok(())
189	}
190	
191	/// Clear the leaf PTE at `va` in the page-table tree rooted at `ttbr0_pa`,
192	/// returning `Some(pa)` of the page that was mapped or `None` if `va` had no
193	/// leaf PTE.
194	///
195	/// This is the body of [`AddrSpace::unmap_page`], exposed as a free function
196	/// for the same reason as [`map_page_in`]: slice-3.3's `VMCTL_PT_UNMAP` clears
197	/// a PTE in a proc's *live* tree given only the `ttbr0_pa` from its
198	/// [`Proc`](crate::proc::Proc) slot. Intermediate L1/L2/L3 tables are left in
199	/// place (lazy pruning happens at [`AddrSpace::destroy`]); the freed PA is the
200	/// caller's to `free_frame` if appropriate.
201	pub fn unmap_page_in(ttbr0_pa: u64, va: u64) -> Option<u64> {
202	    check_va(va).ok()?;
203	    let l1 = next_table(ttbr0_pa, pte_index(va, 0))?;
204	    let l2 = next_table(l1, pte_index(va, 1))?;
205	    let l3 = next_table(l2, pte_index(va, 2))?;
206	    let l3_table = table_mut(l3);
207	    let idx = pte_index(va, 3);
208	    let pte = l3_table[idx];
209	    if pte & PTE_VALID == 0 {
210	        return None;
211	    }
212	    l3_table[idx] = 0;
213	    Some(pte & PA_MASK)
214	}
215	
216	/// Visit every valid L3 leaf mapping in the tree rooted at `ttbr0_pa`,
217	/// calling `f(va, pa, prot)` for each in ascending-VA order.
218	///
219	/// This is the enumeration primitive slice 4.6 needs twice: `SYS_FORK` copies
220	/// every parent page into a fresh child tree, and `SYS_EXIT` frees every leaf
221	/// frame before [`AddrSpace::destroy`] (which only frees the tables). `f` may
222	/// allocate frames and write *other* trees, but must not modify this one —
223	/// each table is snapshotted before its entries are walked (the
224	/// [`free_subtree`] pattern), so mid-walk edits to `ttbr0_pa`'s tree would be
225	/// silently ignored, not honored. Returning `Err` aborts the walk (fork's
226	/// out-of-memory unwind).
227	pub fn walk_leaves(
228	    ttbr0_pa: u64,
229	    f: &mut dyn FnMut(u64, u64, Prot) -> Result<(), MapError>,
230	) -> Result<(), MapError> {
231	    let l0: [u64; PTES_PER_LEVEL] = *table_ref(ttbr0_pa);
232	    for (i0, d0) in l0.iter().enumerate() {
233	        if !is_table_desc(*d0) {
234	            continue;
235	        }
236	        let l1: [u64; PTES_PER_LEVEL] = *table_ref(d0 & PA_MASK);
237	        for (i1, d1) in l1.iter().enumerate() {
238	            if !is_table_desc(*d1) {
239	                continue;
240	            }
241	            let l2: [u64; PTES_PER_LEVEL] = *table_ref(d1 & PA_MASK);
242	            for (i2, d2) in l2.iter().enumerate() {
243	                if !is_table_desc(*d2) {
244	                    continue;
245	                }
246	                let l3: [u64; PTES_PER_LEVEL] = *table_ref(d2 & PA_MASK);
247	                for (i3, d3) in l3.iter().enumerate() {
248	                    if *d3 & PTE_VALID == 0 {
249	                        continue;
250	                    }
251	                    let va = ((i0 as u64) << 39)
252	                        | ((i1 as u64) << 30)
253	                        | ((i2 as u64) << 21)
254	                        | ((i3 as u64) << PAGE_SHIFT);
255	                    f(va, *d3 & PA_MASK, pte_prot(*d3))?;
256	                }
257	            }
258	        }
259	    }
260	    Ok(())
261	}
262	
263	/// The AP bit that distinguishes read-only from read-write at EL0: set in
264	/// `PTE_AP_RO_EL0` (0b11 << 6), clear in `PTE_AP_RW_EL0` (0b01 << 6).
265	const PTE_AP_READONLY_BIT: u64 = PTE_AP_RO_EL0 & !PTE_AP_RW_EL0;
266	
267	/// Recover the mapping intent from a leaf page descriptor — the inverse of
268	/// [`prot_attrs`]. Writable ⇔ the AP read-only bit is clear; executable ⇔
269	/// UXN is clear. Fork uses this to re-install a copied page with the same
270	/// permissions the parent had.
271	fn pte_prot(pte: u64) -> Prot {
272	    Prot {
273	        writable: pte & PTE_AP_READONLY_BIT == 0,
274	        executable: pte & PTE_UXN == 0,
275	    }
276	}
277	
278	/// True when `desc` is a valid table descriptor (at L0–L2 — the only kind of
279	/// valid entry [`ensure_next_table`] writes at those levels; a valid entry
280	/// with `PTE_TABLE` clear would be a block descriptor, which this kernel
281	/// never maps).
282	fn is_table_desc(desc: u64) -> bool {
283	    desc & (PTE_VALID | PTE_TABLE) == (PTE_VALID | PTE_TABLE)
284	}
285	
286	/// Mask selecting the PA bits of a descriptor (47:12).
287	const PA_MASK: u64 = 0x0000_FFFF_FFFF_F000;
288	
289	fn check_va(va: u64) -> Result<(), MapError> {
290	    if va & (FRAME_SIZE as u64 - 1) != 0 {
291	        return Err(MapError::Misaligned);
292	    }
293	    if va >= USER_VA_TOP {
294	        return Err(MapError::OutOfRange);
295	    }
296	    Ok(())
297	}
298	
299	fn pte_index(va: u64, level: u32) -> usize {
300	    let shift = PAGE_SHIFT + 9 * (3 - level);
301	    ((va >> shift) & 0x1FF) as usize
302	}
303	
304	const fn make_table_desc(next_table_pa: u64) -> u64 {
305	    (next_table_pa & PA_MASK) | PTE_VALID | PTE_TABLE
306	}
307	
308	const fn make_page_desc(pa: u64, attrs: u64) -> u64 {
309	    // At L3, both PTE_VALID and PTE_TABLE bits must be set to distinguish a
310	    // page descriptor from an invalid entry. `mmu::make_page_desc` documents
311	    // this; we mirror the same encoding.
312	    (pa & PA_MASK) | PTE_VALID | PTE_TABLE | attrs
313	}
314	
315	/// Borrow the 512-entry table at `table_pa` via HHDM for read.
316	fn table_ref(table_pa: u64) -> &'static [u64; PTES_PER_LEVEL] {
317	    // SAFETY: `table_pa` came from `alloc_frame`, so it is HHDM-mapped and
318	    // 4 KiB-aligned. Single-threaded boot — no concurrent writer.
319	    unsafe { &*(phys_to_hhdm(table_pa) as *const [u64; PTES_PER_LEVEL]) }
320	}
321	
322	/// Borrow the 512-entry table at `table_pa` via HHDM for mutation.
323	fn table_mut(table_pa: u64) -> &'static mut [u64; PTES_PER_LEVEL] {
324	    // SAFETY: `table_pa` came from `alloc_frame`, so it is HHDM-mapped and
325	    // 4 KiB-aligned. Single-threaded boot — no concurrent reader/writer.
326	    unsafe { &mut *(phys_to_hhdm(table_pa) as *mut [u64; PTES_PER_LEVEL]) }
327	}
328	
329	/// Return the PA of the child table at `parent[idx]`, or `None` if the slot
330	/// is empty or holds a non-table descriptor.
331	fn next_table(parent_pa: u64, idx: usize) -> Option<u64> {
332	    let desc = table_ref(parent_pa)[idx];
333	    if desc & PTE_VALID == 0 {
334	        return None;
335	    }
336	    // At L0/L1/L2, a table descriptor has PTE_TABLE=1; a valid entry with
337	    // PTE_TABLE=0 is a *block* descriptor (2 MiB / 1 GiB block) and must
338	    // NOT be followed as a sub-table. Slice 3.1a only ever writes table
339	    // descriptors via `ensure_next_table`, so this branch never fires
340	    // today — the check is future-proofing for any later slice that maps
341	    // a block (large-page support, identity ranges, etc.). (L3 page
342	    // descriptors also have PTE_TABLE=1, but we never call `next_table`
343	    // at L3.)
344	    if desc & PTE_TABLE == 0 {
345	        return None;
346	    }
347	    Some(desc & PA_MASK)
348	}
349	
350	/// Return the PA of the child table at `parent[idx]`, allocating and
351	/// linking it if absent.
352	fn ensure_next_table(parent_pa: u64, idx: usize) -> Result<u64, MapError> {
353	    let parent = table_mut(parent_pa);
354	    let desc = parent[idx];
355	    if desc & PTE_VALID != 0 {
356	        return Ok(desc & PA_MASK);
357	    }
358	    let child = alloc_frame().ok_or(MapError::OutOfMemory)?;
359	    parent[idx] = make_table_desc(child.addr());
360	    Ok(child.addr())
361	}
362	
363	/// Recursively free every intermediate table under `table_pa` at the given
364	/// `level` (0 = L0 root, 3 = L3 leaves). Page descriptors at L3 are left
365	/// alone (caller owns leaf frames); the table itself at L3 is freed by
366	/// the L2 recursion call. The L0 root is freed by [`AddrSpace::destroy`].
367	fn free_subtree(table_pa: u64, level: u32) {
368	    if level >= 3 {
369	        // L3 contains page descriptors, not table descriptors — nothing to
370	        // recurse into. The L3 frame itself was already linked at L2 and
371	        // will be freed by the L2 caller.
372	        return;
373	    }
374	    // Snapshot the entries into a local so the HHDM borrow of `table_pa`
375	    // ends before the recursive call (which takes fresh borrows of sibling
376	    // tables — overlapping `&` is fine for shared reads, but copying makes
377	    // the intent unambiguous).
378	    let entries: [u64; PTES_PER_LEVEL] = *table_ref(table_pa);
379	    for desc in entries.iter() {
380	        if *desc & PTE_VALID == 0 {
381	            continue;
382	        }
383	        let child_pa = *desc & PA_MASK;
384	        // Recurse to free grandchildren first, then free this child table.
385	        free_subtree(child_pa, level + 1);
386	        free_frame(Frame::from_addr(child_pa));
387	    }
388	}
