52	/// Running total of IPC calls dispatched. Sampled at [`TRACE_EVERY`]
53	/// intervals for the boot-time observability trace.
54	static CALL_COUNT: AtomicU64 = AtomicU64::new(0);
55	
56	/// Cadence of the boot-time IPC trace. ~600 IPC ops/sec under the
57	/// slice-2.5 ping-pong demo → ~6 trace lines/sec; well under PL011's
58	/// ~290 lines/sec ceiling at 115200 baud.
59	///
60	/// TODO(phase 4): once servers come online and per-second IPC rate
61	/// jumps an order of magnitude, this needs to become a runtime knob
62	/// (DS_SUBSCRIBE-driven) or scale by load.
63	const TRACE_EVERY: u64 = 100;
64	
65	/// Number of leading SVCs to trace unconditionally, regardless of
66	/// [`TRACE_EVERY`]. Gives the early-boot output enough granularity to
67	/// show each stub's first IPC call — slice 2.6 added a third stub (C)
68	/// whose fast-path SENDRECs to SYSTEM outpace stubs A and B by orders
69	/// of magnitude, so without this aid the slice-2.5 ping-pong looks like
70	/// it regressed even though A↔B are still cooperating fine. Slice 4.5
71	/// widened 12 → 24: six boot servers' startup SENDRECs (GET_WHOAMI +
72	/// DS publish + replies + RS's first heartbeat round) exceed the old
73	/// window. PM itself boots after stub C's kernel-call flood begins, so
74	/// its handshake still lands past any practical head window — the
75	/// `[ksys SYS_PRIVCTL] target=E` trace is PM's boot evidence instead
76	/// (it can only fire after PM's GET_WHOAMI + DS publish succeeded).
77	const TRACE_HEAD: u64 = 24;
78	
79	/// IPC dispatch. Called from `trap.S` immediately after the SVC entry
80	/// stub has saved the caller's registers into `frame`.
81	///
82	/// Argument convention (mirrors MINIX 3 `kernel/proc.c:609 do_ipc`):
83	///
84	/// | reg | meaning                          |
85	/// |-----|----------------------------------|
86	/// | x0  | source/destination endpoint      |
87	/// | x1  | IPC primitive number             |
88	/// | x2  | pointer to the user's `Message`  |
89	/// | x3  | (SENDA only) table length        |
90	///
91	/// The result is written back into `frame.x[0]` — the SVC restore path
92	/// puts it in the caller's `x0` on `eret`.
93	#[unsafe(no_mangle)]
94	pub extern "C" fn do_ipc(frame: &mut ArchRegisterFrame) {
95	    let src_dst_e: Endpoint = frame.x[0] as i32;
96	    let call_nr: i32 = frame.x[1] as i32;
97	    let user_msg_va: u64 = frame.x[2];
98	    let extra: u64 = frame.x[3];
99	
100	    // SAFETY: SVC dispatch is single-threaded (DAIF.I masked at EL1); no
101	    // other code can write to PROC_TABLE/PRIV_TABLE before we return.
102	    let proc_table = unsafe { proc_table_mut_slice() };
103	    let priv_table = unsafe { priv_table_mut_slice() };
104	
105	    let cur_raw = CURRENT_PROC_NR.load(Ordering::Relaxed);
106	    let caller_nr = ProcNr::new(cur_raw);
107	
108	    let result = dispatch(
109	        proc_table,
110	        priv_table,
111	        caller_nr,
112	        call_nr,
113	        src_dst_e,
114	        user_msg_va,
115	        extra,
116	    );
117	
118	    frame.x[0] = result as u64;
119	
120	    let n = CALL_COUNT.fetch_add(1, Ordering::Relaxed) + 1;
121	    if n <= TRACE_HEAD || n.is_multiple_of(TRACE_EVERY) {
122	        let mut uart = Uart::new();
123	        let _ = writeln!(
124	            uart,
125	            "[ipc {n}] caller={caller_nr} call={call_nr} target={src_dst_e:#x} result={result}",
126	        );
127	    }
128	}
