238	/// `SENDREC` is the atomic-send-then-receive primitive used by every
239	/// `_syscall()` wrapper. SEND half blocks (or delivers); on success we
240	/// mark `MF_REPLY_PEND` and run the RECEIVE half against the same partner.
241	fn do_sendrec(
242	    proc_table: &mut [Proc; N_PROC_SLOTS],
243	    priv_table: &mut [Priv; NR_SYS_PROCS],
244	    caller_nr: ProcNr,
245	    dst_e: Endpoint,
246	    user_msg_va: u64,
247	) -> i32 {
248	    let send_result = send::mini_send(
249	        proc_table,
250	        priv_table,
251	        caller_nr,
252	        dst_e,
253	        user_msg_va,
254	        SendFlags::Blocking,
255	    );
256	    if send_result != OK {
257	        return send_result;
258	    }
259	    let Some(caller_idx) = proc_index(caller_nr) else {
260	        return EBADCALL;
261	    };
262	    proc_table[caller_idx].misc_flags |= MF_REPLY_PEND;
263	    receive::mini_receive(
264	        proc_table,
265	        priv_table,
266	        caller_nr,
267	        dst_e,
268	        user_msg_va,
269	        RecvFlags::Blocking,
270	    )
271	}
