273	/// Copy a pending IPC message out to the user buffer recorded at
274	/// RECEIVE-time and clear `MF_DELIVERMSG`. Called from
275	/// `sched::schedule_next` on every EL1 → EL0 transition.
276	pub fn flush_deliver_msg(p: &mut Proc) {
277	    if p.misc_flags & MF_DELIVERMSG == 0 {
278	        return;
279	    }
280	    // Best-effort; if the user buffer is bad, slice 2.5 has no place to
281	    // signal that (the receiver hasn't returned yet). Phase 3 adds
282	    // MF_MSGFAILED + signal delivery to handle this. The bounds check
283	    // in `copy_msg_to_user` keeps an out-of-range VA from faulting EL1.
284	    let _ = message::copy_msg_to_user(p.deliver_msg_vir, &p.deliver_msg);
285	    p.misc_flags &= !MF_DELIVERMSG;
286	}
