320	/// Cadence of the boot-time alarm-fire trace.
321	const ALARM_TRACE_EVERY: u64 = 100;
322	/// Leading alarm fires to trace unconditionally (head carve-out), so RS's first
323	/// few periodic fires show even though stub C's `SYS_GETINFO` flood dwarfs the
324	/// modulo sampler (same reasoning as [`TRACE_HEAD`] / `sched::NOQ_TRACE_HEAD`).
325	const ALARM_TRACE_HEAD: u64 = 6;
326	/// Count of alarm fires, for the head/modulo trace above.
327	static ALARM_COUNT: AtomicU64 = AtomicU64::new(0);
328	
329	/// Fire every per-proc one-shot alarm due at or before `now` (slice 4.4).
330	///
331	/// Called from `clock::tick` *only* when the `EARLIEST_ALARM` fast-path gate
332	/// says an alarm is due, so the O(N) proc-table scan is paid rarely. For each
333	/// expired [`Proc::alarm_at`] it clears the field, delivers a kernel-originated
334	/// `NOTIFY` from `CLOCK` to the owner ([`notify::deliver_alarm`]), and traces
335	/// the fire; it then recomputes the minimum of the still-armed deadlines and
336	/// writes it back into the clock gate via [`crate::clock::set_earliest_alarm`].
337	///
338	/// Materializes the proc/priv slices here — same "only `ipc` materializes the
339	/// tables for delivery" discipline as [`send_pagefault_to_vm`] /
340	/// [`send_no_quantum`].
341	///
342	/// [`Proc::alarm_at`]: crate::proc::Proc::alarm_at
343	pub fn fire_expired_alarms(now: u64) {
344	    // SAFETY: IRQ/clock context — single-threaded, DAIF.I masked. `clock::tick`
345	    // has taken no PROC_TABLE/PRIV_TABLE borrow before calling us.
346	    let proc_table = unsafe { proc_table_mut_slice() };
347	    let priv_table = unsafe { priv_table_mut_slice() };
348	
349	    let mut next_earliest: u64 = 0;
350	    for idx in 0..N_PROC_SLOTS {
351	        let at = proc_table[idx].alarm_at;
352	        if at == 0 {
353	            continue; // disarmed slot
354	        }
355	        if at > now {
356	            next_earliest = fold_earliest(next_earliest, at); // armed but not yet due
357	            continue;
358	        }
359	        // Due: disarm, deliver the CLOCK notification, trace the fire.
360	        proc_table[idx].alarm_at = 0;
361	        notify::deliver_alarm(proc_table, priv_table, idx);
362	        trace_alarm_fire(proc_table[idx].name[0], proc_table[idx].nr, now);
363	    }
364	
365	    crate::clock::set_earliest_alarm(next_earliest);
366	}
