368	/// Fold one still-armed deadline `at` into the running next-earliest, treating
369	/// 0 as "none". Pulled out of [`fire_expired_alarms`] to keep that scan flat.
370	fn fold_earliest(current: u64, at: u64) -> u64 {
371	    if current == 0 || at < current {
372	        at
373	    } else {
374	        current
375	    }
376	}
