378	/// Emit the head/modulo-sampled `[alarm N]` fire trace. Bumps the fire counter
379	/// and prints only on the head carve-out or every [`ALARM_TRACE_EVERY`]th fire
380	/// — kept out of [`fire_expired_alarms`] so its scan stays under the cognitive-
381	/// complexity bar.
382	fn trace_alarm_fire(name0: u8, nr: ProcNr, now: u64) {
383	    let n = ALARM_COUNT.fetch_add(1, Ordering::Relaxed) + 1;
384	    if n > ALARM_TRACE_HEAD && !n.is_multiple_of(ALARM_TRACE_EVERY) {
385	        return;
386	    }
387	    let id = if name0 != 0 { name0 } else { b'?' };
388	    let _ = writeln!(
389	        Uart::new(),
390	        "[alarm {n}] owner={} nr={} at={now}",
391	        id as char,
392	        nr.get()
393	    );
394	}
