402	#[unsafe(no_mangle)]
403	pub extern "C" fn el1_svc_tail() {
404	    // SAFETY: SVC dispatch context — single-threaded, DAIF.I masked,
405	    // no other PROC_TABLE/RUNQ references live at this point.
406	    unsafe { sched::schedule_next() }
407	}
