164	/// `SYS_VMCTL` / `SYS_SCHEDULE` / `SYS_SCHEDCTL` and the slice-4.5 signal trio
165	/// (`SYS_KILL` / `SYS_GETKSIG` / `SYS_ENDKSIG`) act on a *target* proc named in
166	/// the message, so they take the whole `proc_table` + `caller_nr` (and
167	/// `do_kill` / `do_exit` additionally write `notify_pending` bitmaps, which is
168	/// why `priv_table` is `&mut`). Every other handler acts only on the caller,
169	/// so it gets a single caller slot re-borrowed inside its arm (see
170	/// [`dispatch_caller_local`]).
171	fn kernel_call_dispatch(
172	    proc_table: &mut [Proc; N_PROC_SLOTS],
173	    priv_table: &mut [Priv; NR_SYS_PROCS],
174	    caller_nr: ProcNr,
175	    msg: &mut Message,
176	) -> i32 {
177	    let caller_idx = proc_index(caller_nr).expect("caller in proc table");
178	    let caller_priv_id = proc_table[caller_idx]
179	        .priv_id
180	        .expect("caller priv populated");
181	
182	    let call_idx = msg.m_type - KERNEL_CALL;
183	    if call_idx < 0 || (call_idx as usize) >= NR_SYS_CALLS {
184	        return EBADREQUEST;
185	    }
186	    let call_idx = call_idx as usize;
187	
188	    if !get_call_bit(&priv_table[caller_priv_id.as_usize()].k_call_mask, call_idx) {
189	        return ECALLDENIED;
190	    }
191	
192	    // Calls that act on a *target* proc named in the message take the whole
193	    // table + caller_nr; route them before the caller-local dispatch.
194	    match msg.m_type {
195	        SYS_VMCTL => return do_vmctl::do_vmctl(proc_table, caller_nr, msg),
196	        SYS_SCHEDULE => return do_schedule::do_schedule(proc_table, caller_nr, msg),
197	        SYS_SCHEDCTL => return do_schedule::do_schedctl(proc_table, caller_nr, msg),
198	        SYS_KILL => return do_sig::do_kill(proc_table, priv_table, caller_nr, msg),
199	        SYS_GETKSIG => return do_sig::do_getksig(proc_table, caller_nr, msg),
200	        SYS_ENDKSIG => return do_sig::do_endksig(proc_table, caller_nr, msg),
201	        SYS_EXIT => return do_exit::do_exit(proc_table, priv_table, caller_nr, msg),
202	        SYS_FORK => return do_fork::do_fork(proc_table, caller_nr, msg),
203	        SYS_EXEC => return do_exec::do_exec(proc_table, caller_nr, msg),
204	        SYS_PRIVCTL => return do_privctl::do_privctl(proc_table, caller_nr, msg),
205	        _ => {}
206	    }
207	
208	    // proc_table and priv_table are disjoint statics, so borrowing one slot
209	    // in each is permitted.
210	    let caller = &mut proc_table[caller_idx];
211	    let caller_priv = &priv_table[caller_priv_id.as_usize()];
212	    dispatch_caller_local(caller, caller_priv, msg)
213	}
