215	/// Dispatch the caller-only kernel calls (everything except `SYS_VMCTL`).
216	///
217	/// The const assert locks the arm count — adding a new `SYS_*` without a new
218	/// arm here is a compile error.
219	fn dispatch_caller_local(caller: &mut Proc, caller_priv: &Priv, msg: &mut Message) -> i32 {
220	    const _: () = assert!(
221	        NR_KERN_CALLS_PHASE4 == 18,
222	        "expand kernel_call_dispatch when a new SYS_* lands",
223	    );
224	    match msg.m_type {
225	        SYS_GETINFO => do_getinfo::do_getinfo(caller, caller_priv, msg),
226	        SYS_COPY => stubs::do_copy(caller, caller_priv, msg),
227	        SYS_SAFECOPY => stubs::do_safecopy(caller, caller_priv, msg),
228	        SYS_IRQCTL => stubs::do_irqctl(caller, caller_priv, msg),
229	        // SYS_VMCTL / SYS_SCHEDULE / SYS_SCHEDCTL / SYS_KILL / SYS_GETKSIG /
230	        // SYS_ENDKSIG / SYS_EXIT / SYS_FORK / SYS_EXEC / SYS_PRIVCTL are handled
231	        // in `kernel_call_dispatch` (they act on a target proc and need the table).
232	        SYS_SETALARM => do_setalarm::do_setalarm(caller, caller_priv, msg),
233	        SYS_TIMES => stubs::do_times(caller, caller_priv, msg),
234	        SYS_DIAGCTL => stubs::do_diagctl(caller, caller_priv, msg),
235	        SYS_SETGRANT => stubs::do_setgrant(caller, caller_priv, msg),
236	        _ => EBADREQUEST,
237	    }
238	}
