33	// `do_privctl` / `do_exit` are real handlers as of slice 4.5 — see
34	// `system::do_privctl` / `system::do_exit`.
35	// `do_fork` is a real handler as of slice 4.6 — see `system::do_fork`.
36	enosys_stub!(do_times);
37	enosys_stub!(do_diagctl);
38	enosys_stub!(do_setgrant);
39	// `do_kill` / `do_getksig` / `do_endksig` are real handlers as of slice 4.5 —
